package com.optarena.app;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.web.servlet.MockMvc;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class RegistrationHiddenTest {

    @Autowired
    private MockMvc mvc;

    private void expect(String body, int statusCode) throws Exception {
        mvc.perform(post("/register").contentType("application/json").content(body))
           .andExpect(status().is(statusCode));
    }

    @Test
    void validRegistrationCreated() throws Exception {
        mvc.perform(post("/register").contentType("application/json")
                .content("{\"username\": \"ada\", \"age\": 30}"))
           .andExpect(status().isCreated())
           .andExpect(jsonPath("$.username").value("ada"))
           .andExpect(jsonPath("$.age").value(30));
    }

    @Test
    void boundaryAgesAccepted() throws Exception {
        expect("{\"username\": \"a\", \"age\": 13}", 201);
        expect("{\"username\": \"b\", \"age\": 120}", 201);
    }

    @Test
    void tooYoungRejected() throws Exception {
        mvc.perform(post("/register").contentType("application/json")
                .content("{\"username\": \"kid\", \"age\": 12}"))
           .andExpect(status().isBadRequest())
           .andExpect(jsonPath("$.error").exists());
    }

    @Test
    void tooOldRejected() throws Exception {
        expect("{\"username\": \"methuselah\", \"age\": 121}", 400);
    }

    @Test
    void blankUsernameRejected() throws Exception {
        expect("{\"username\": \"   \", \"age\": 30}", 400);
    }

    @Test
    void missingAgeRejected() throws Exception {
        expect("{\"username\": \"ada\"}", 400);
    }
}

